/**
 * Shared helpers for WorkflowBuilder settings toggle and WorkflowLicense.
 *
 * Both components use the same subscription dialog flow and setting store
 * interactions. Extracted to avoid duplicating the logic.
 */
import { notify } from 'src/components/notifications/notify';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { CONSTANTS } from 'src/constants';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

export const WORKFLOW_SETTING_NAME = 'WORKFLOW_BUILDER_MODULE_SETTING';
export const WORKFLOW_CELERY_SETTING_NAME = 'WORKFLOW_CELERY_SETTING';
export const WORKFLOW_DOC_FLOW_KEY = CONSTANTS.docflow;
export const ADVANCED_WORKFLOW_SETTING_NAME = 'ADVANCED_WORKFLOW_MODULE_SETTING';
export const ADVANCED_WORKFLOW_APP_KEY = CONSTANTS.docflow_advanced;

// ---------------------------------------------------------------------------
// Context interface — both components supply this via `this`
// ---------------------------------------------------------------------------

export interface WorkflowBuilderContext {
  user_settings: dynamicObj;
  show_popup: boolean;
  loading: boolean;
  updateSetting: (key: string, value: any) => Promise<void>;
  showLoading: () => void;
  hideLoading: () => void;
  $t: (key: string) => string;
}

// ---------------------------------------------------------------------------
// Extracted methods
// ---------------------------------------------------------------------------

export async function saveSettingsImpl(ctx: WorkflowBuilderContext, key: string, value: any) {
  if (!key) {
    return;
  }
  try {
    ctx.loading = true;
    ctx.showLoading();
    await ctx.updateSetting(key, value);
    notify.success(ctx.$t('MSG_SAVE'));
  } catch (err: any) {
    const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
    notify.error(msg);
    logError(err);
  } finally {
    ctx.loading = false;
    ctx.hideLoading();
  }
}

export async function setWorkflowBuilderImpl(ctx: WorkflowBuilderContext, val: boolean) {
  try {
    if (val) {
      // Revert the toggle first
      ctx.user_settings[WORKFLOW_SETTING_NAME] = false;
      // Show dialog to confirm subscription
      ctx.show_popup = true;
    } else {
      // Disabling - save the setting directly (saveSettingsImpl handles loading state)
      await saveSettingsImpl(ctx, WORKFLOW_SETTING_NAME, false);
    }
  } catch (err: any) {
    const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
    notify.error(msg);
    logError(err);
  } finally {
    ctx.hideLoading();
  }
}

export function handleSubscriptionConfirmImpl(ctx: WorkflowBuilderContext, value: any) {
  ctx.user_settings[WORKFLOW_SETTING_NAME] = value;
}

/**
 * Initialise setting defaults when loading finishes.
 * Used as the handler body for the `loading_settings` watcher.
 */
export function onLoadingSettingsChange(ctx: WorkflowBuilderContext, newVal: boolean, oldVal: boolean) {
  if (newVal === false && oldVal === true) {
    if (!ctx.user_settings[WORKFLOW_SETTING_NAME]) {
      ctx.user_settings[WORKFLOW_SETTING_NAME] = false;
    }
    if (!ctx.user_settings[WORKFLOW_CELERY_SETTING_NAME]) {
      ctx.user_settings[WORKFLOW_CELERY_SETTING_NAME] = false;
    }
    if (!ctx.user_settings[ADVANCED_WORKFLOW_SETTING_NAME]) {
      ctx.user_settings[ADVANCED_WORKFLOW_SETTING_NAME] = false;
    }
  }
}
